import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { parseCSV, parsePDF } from '@/lib/parsers'
import { createHash } from 'crypto'
// 1. IMPORT THE TYPE FROM YOUR PARSER
import { ParsedTransaction } from '@/lib/parsers/pdf' 

export const dynamic = 'force-dynamic'

export async function POST(request: NextRequest) {
  try {
    const supabase = await createClient()
    const { data: { user }, error: authError } = await supabase.auth.getUser()

    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const formData = await request.formData()
    const file = formData.get('file') as File | null
    const bankAccountId = formData.get('bank_account_id') as string | null

    if (!file || !bankAccountId) {
      return NextResponse.json({ error: 'Missing file or bank account' }, { status: 400 })
    }

    // Verify bank account belongs to user
    const { data: bankAccount, error: bankError } = await supabase
      .from('bank_accounts')
      .select('id')
      .eq('id', bankAccountId)
      .eq('user_id', user.id)
      .single()

    if (bankError || !bankAccount) {
      return NextResponse.json({ error: 'Invalid bank account' }, { status: 400 })
    }

    const bytes = await file.arrayBuffer()
    const buffer = Buffer.from(bytes)
    const fileHash = createHash('sha256').update(buffer).digest('hex')

    // Check for duplicate import
    const { data: existingImport } = await supabase
      .from('imports')
      .select('id, filename')
      .eq('user_id', user.id)
      .eq('file_hash', fileHash)
      .maybeSingle()

    if (existingImport) {
      return NextResponse.json(
        { error: `This file was already imported as "${existingImport.filename}"` },
        { status: 409 }
      )
    }

    const filename = file.name.toLowerCase()
    const isCSV = filename.endsWith('.csv')
    const isPDF = filename.endsWith('.pdf')

    if (!isCSV && !isPDF) {
      return NextResponse.json({ error: 'Unsupported file type' }, { status: 400 })
    }

    let parseResult
    try {
      if (isCSV) {
        const content = buffer.toString('utf-8')
        parseResult = parseCSV(content)
      } else {
        parseResult = await parsePDF(buffer)
      }
    } catch (parseError) {
      return NextResponse.json({ error: 'Failed to parse file' }, { status: 400 })
    }

    if (!parseResult.transactions || parseResult.transactions.length === 0) {
      return NextResponse.json({ error: 'No transactions found' }, { status: 400 })
    }

    // Create import record
    const { data: importRecord, error: importError } = await supabase
      .from('imports')
      .insert({
        user_id: user.id,
        bank_account_id: bankAccountId,
        filename: file.name,
        file_hash: fileHash,
        import_type: isCSV ? 'csv' : 'pdf',
        transaction_count: parseResult.transactions.length,
      })
      .select()
      .single()

    if (importError || !importRecord) {
      return NextResponse.json({ error: 'Failed to create import record' }, { status: 500 })
    }

    // 2. APPLY THE TYPE TO THE MAP CALLBACK
    const transactionsToInsert = parseResult.transactions.map((t: ParsedTransaction) => ({
      user_id: user.id,
      bank_account_id: bankAccountId,
      import_id: importRecord.id,
      amount: t.amount,
      date: t.date,
      name: t.name?.substring(0, 255) || 'Unknown',
      merchant_name: t.merchant_name?.substring(0, 255) || 'Unknown',
      category: t.category,
    }))

    // Batch Insert
    const BATCH_SIZE = 100
    let insertedCount = 0

    for (let i = 0; i < transactionsToInsert.length; i += BATCH_SIZE) {
      const batch = transactionsToInsert.slice(i, i + BATCH_SIZE)
      const { error: insertError } = await supabase.from('transactions').insert(batch)

      if (insertError) {
        await supabase.from('imports').delete().eq('id', importRecord.id)
        return NextResponse.json({ error: 'Failed to save transactions' }, { status: 500 })
      }
      insertedCount += batch.length
    }

    return NextResponse.json({
      success: true,
      import_id: importRecord.id,
      transactions_imported: insertedCount,
      parse_errors: parseResult.errors,
    })

  } catch (error) {
    console.error('Import error:', error)
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

